_AGILLM_ALIBI_MODE = "legacy"
_AGILLM_ALIBI_SCALE = 1.0
_AGILLM_LR_SCHEDULE_ORIGIN_TOK = 0
_AGILLM_REPAIR_ACTIVE = False
_AGILLM_REPAIR_SCHEMA = "agillm43.repair.v5.5"
