_AGILLM_DBLOCK_RESUME_SCHEMA = "agillm43.dblock.resume.v6"
_AGILLM_REPAIR_CONTRACT_SCHEMA = "agillm43.repair.contract.v10"
_AGILLM43_PRODUCTION_SCHEMA = "agillm43.production.v15"
_AGILLM43_CONTINUATION_BUDGET_SCHEMA = "agillm43.continuation_budget.v1"
_AGILLM43_PRODUCTION_DBLOCK_RESUME_SCHEMA = (
    "agillm43.production.dblock.resume.v1"
)
