def _repair_expected_digest_arg(args, name):
    raw = str(getattr(args, name, "") or "").strip().lower()
    if raw.startswith("sha256:"):
        raw = raw.split(":", 1)[1].strip()
    return raw


def _repair_dataset_contract_receipt(args):
    specs = tuple(_dataset_specs_csv(getattr(args, "source", "")))
    raw = json.dumps(list(specs), separators=(",", ":"), ensure_ascii=True).encode("utf-8")
    digest = hashlib.sha256(raw).hexdigest()
    expected = _repair_expected_digest_arg(args, "repair_dataset_sha256")
    if expected != _AGILLM43_REPAIR_SOURCE_SHA256:
        raise RuntimeError(
            "--repair_dataset_sha256 must explicitly equal the reviewed ten-source contract "
            + _AGILLM43_REPAIR_SOURCE_SHA256)
    if specs != _AGILLM43_REPAIR_SOURCE_SPECS or digest != _AGILLM43_REPAIR_SOURCE_SHA256:
        raise RuntimeError(
            f"repair training source drift: sha256={digest} specs={list(specs)!r}")
    mutable = sorted(
        key for key in os.environ
        if (key.startswith("AGILLM_DATASET_") or key in _AGILLM43_MUTABLE_DATASET_ENV_EXACT)
    )
    if mutable:
        raise RuntimeError(
            "strict repair rejects mutable dataset/router environment overrides: "
            + ", ".join(mutable))
    return {
        "schema": _AGILLM43_REPAIR_DATASET_SCHEMA,
        "example_boundary_policy": _AGILLM43_EXAMPLE_BOUNDARY_POLICY,
        "cropped_examples_end_with_eos": True,
        "crop_rng_compatible_with_v11": True,
        "crop_output_length_preserved": True,
        "eos_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
        "source_sha256": digest,
        "source_specs": list(specs),
        "source_count": len(specs),
        "hot_config": False,
        "router_state": False,
        "agent_router": False,
        "source_floors": False,
        "max_example_tokens": 4096,
        "remote_shards_per_iter": 4,
    }


def _repair_heldout_contract_receipt(args, val_receipt):
    if not isinstance(val_receipt, dict):
        raise RuntimeError("heldout-v2 validation receipt is missing")
    token_path = pathlib.Path(val_receipt["path"])
    token_expected = _repair_val_expected_sha256(args)
    manifest_expected = _repair_expected_digest_arg(args, "repair_val_manifest_sha256")
    if token_expected != _AGILLM43_HELDOUT_TOKEN_IDS_SHA256:
        raise RuntimeError(
            "--val_sha256 must explicitly equal heldout-v2 token_ids SHA256 "
            + _AGILLM43_HELDOUT_TOKEN_IDS_SHA256)
    if str(val_receipt.get("sha256") or "") != _AGILLM43_HELDOUT_TOKEN_IDS_SHA256:
        raise RuntimeError("validation input is not the reviewed heldout-v2 token_ids.json")
    if manifest_expected != _AGILLM43_HELDOUT_MANIFEST_SHA256:
        raise RuntimeError(
            "--repair_val_manifest_sha256 must explicitly equal "
            + _AGILLM43_HELDOUT_MANIFEST_SHA256)
    manifest_path = token_path.parent / "MANIFEST.json"
    if not manifest_path.is_file():
        raise RuntimeError(f"heldout-v2 manifest is missing: {manifest_path}")
    manifest_sha = _sha256_file(manifest_path)
    if manifest_sha != _AGILLM43_HELDOUT_MANIFEST_SHA256:
        raise RuntimeError(
            f"heldout-v2 manifest checksum mismatch: {manifest_sha}")
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RuntimeError(f"heldout-v2 manifest cannot be parsed: {exc}") from exc
    files = manifest.get("files") if isinstance(manifest, dict) else None
    token_entry = files.get("token_ids.json") if isinstance(files, dict) else None
    tokenizer_entry = files.get("checkpoint_tokenizer_sidecar.json") if isinstance(files, dict) else None
    if str(manifest.get("schema") or "") != "agillm43.heldout.manifest.v2":
        raise RuntimeError("heldout-v2 manifest schema mismatch")
    if not isinstance(token_entry, dict) or str(token_entry.get("sha256") or "") != _AGILLM43_HELDOUT_TOKEN_IDS_SHA256:
        raise RuntimeError("heldout-v2 manifest does not bind token_ids.json")
    if not isinstance(tokenizer_entry, dict) or str(tokenizer_entry.get("sha256") or "") != _AGILLM43_REPAIR_TOKENIZER_SIDECAR_SHA256:
        raise RuntimeError("heldout-v2 manifest does not bind the checkpoint tokenizer sidecar")
    return {
        "schema": "agillm43.repair.heldout.v2",
        "token_ids_path": str(token_path.resolve()),
        "token_ids_sha256": _AGILLM43_HELDOUT_TOKEN_IDS_SHA256,
        "tokens": int(val_receipt["tokens"]),
        "manifest_path": str(manifest_path.resolve()),
        "manifest_sha256": manifest_sha,
        "checkpoint_tokenizer_sidecar_sha256": _AGILLM43_REPAIR_TOKENIZER_SIDECAR_SHA256,
    }


def _repair_import_tokenizer_receipt():
    if bool(SYNTHETIC_TOKENIZER) or str(
            os.environ.get("AGILLM_SYNTHETIC_TOKENIZER", "") or ""
            ).strip().lower() in {"1", "true", "yes"}:
        raise RuntimeError("synthetic tokenizer is forbidden in strict repair")
    configured_id = str(os.environ.get("TOKENIZER_ID", "") or "").strip()
    if configured_id != _AGILLM43_REPAIR_TOKENIZER_ID:
        raise RuntimeError(
            "TOKENIZER_ID must be explicitly pinned to "
            + _AGILLM43_REPAIR_TOKENIZER_ID)
    configured_raw = str(os.environ.get("TOKENIZER_DIR", "") or "").strip()
    expected_dir = _AGILLM43_REPAIR_TOKENIZER_DIR
    if configured_raw != str(expected_dir):
        raise RuntimeError(
            f"TOKENIZER_DIR must be explicitly pinned to {expected_dir}")
    configured_dir = pathlib.Path(configured_raw)
    if configured_dir.is_symlink() or configured_dir.resolve() != expected_dir:
        raise RuntimeError("TOKENIZER_DIR is non-canonical or symlinked")
    tokenizer_json = configured_dir / "tokenizer.json"
    if (not tokenizer_json.is_file()) or tokenizer_json.is_symlink():
        raise RuntimeError("pinned tokenizer.json is missing or unsafe")
    tokenizer_json_sha = _sha256_file(tokenizer_json)
    if tokenizer_json_sha != _AGILLM43_REPAIR_TOKENIZER_JSON_SHA256:
        raise RuntimeError(
            f"pinned tokenizer.json checksum mismatch: {tokenizer_json_sha}")
    try:
        backend = tok.backend_tokenizer.to_str()
        backend_sha = hashlib.sha256(backend.encode("utf-8")).hexdigest()
        vocab = tok.get_vocab()
        runtime = {
            "backend_sha256": backend_sha,
            "vocab_size": max(vocab.values()) + 1,
            "pad_token_id": int(getattr(tok, "pad_token_id", -1)),
            "eos_token_id": int(getattr(tok, "eos_token_id", -1)),
            "nat_mask_token_id": int(vocab.get(NAT_MASK_RECOVERY_TOKEN, -1)),
        }
    except Exception as exc:
        raise RuntimeError(f"cannot inspect import-time tokenizer runtime: {exc}") from exc
    expected_runtime = {
        "backend_sha256": _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256,
        "vocab_size": _AGILLM43_REPAIR_VOCAB,
        "pad_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
        "eos_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
        "nat_mask_token_id": _AGILLM43_REPAIR_NAT_MASK_ID,
    }
    if runtime != expected_runtime:
        raise RuntimeError(
            f"import-time tokenizer runtime mismatch: {runtime!r} != "
            f"{expected_runtime!r}")
    if int(VOCAB) != _AGILLM43_REPAIR_VOCAB or int(BLANK) != 1 or int(EOS) != 1:
        raise RuntimeError(
            f"import-time tokenizer globals drifted: VOCAB={VOCAB} "
            f"BLANK={BLANK} EOS={EOS}")
    return {
        "configured_tokenizer_id": configured_id,
        "configured_tokenizer_dir": str(configured_dir.resolve()),
        "tokenizer_json_path": str(tokenizer_json.resolve()),
        "tokenizer_json_sha256": tokenizer_json_sha,
        "runtime": runtime,
    }


def _repair_tokenizer_contract_receipt(args, checkpoint_path, *, require_runtime, seed_resume):
    import_runtime = _repair_import_tokenizer_receipt()
    sidecar_expected = _repair_expected_digest_arg(args, "repair_tokenizer_sidecar_sha256")
    backend_expected = _repair_expected_digest_arg(args, "repair_tokenizer_backend_sha256")
    if sidecar_expected != _AGILLM43_REPAIR_TOKENIZER_SIDECAR_SHA256:
        raise RuntimeError(
            "--repair_tokenizer_sidecar_sha256 must explicitly equal "
            + _AGILLM43_REPAIR_TOKENIZER_SIDECAR_SHA256)
    if backend_expected != _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256:
        raise RuntimeError(
            "--repair_tokenizer_backend_sha256 must explicitly equal "
            + _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256)
    checkpoint_path = pathlib.Path(checkpoint_path)
    sidecar_path = pathlib.Path(str(checkpoint_path) + ".tokenizer.json")
    if not sidecar_path.is_file():
        raise RuntimeError(f"checkpoint tokenizer sidecar is missing: {sidecar_path}")
    sidecar_sha = _sha256_file(sidecar_path)
    if seed_resume and sidecar_sha != _AGILLM43_REPAIR_TOKENIZER_SIDECAR_SHA256:
        raise RuntimeError(
            f"immutable seed tokenizer sidecar checksum mismatch: {sidecar_sha}")
    try:
        payload = json.loads(sidecar_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RuntimeError(f"checkpoint tokenizer sidecar cannot be parsed: {exc}") from exc
    backend = payload.get("tokenizer_json") if isinstance(payload, dict) else None
    if not isinstance(backend, str) or not backend:
        raise RuntimeError("checkpoint tokenizer sidecar has no tokenizer_json")
    backend_sha = hashlib.sha256(backend.encode("utf-8")).hexdigest()
    special = payload.get("tokenizer_special") if isinstance(payload, dict) else None
    if backend_sha != _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256:
        raise RuntimeError(f"checkpoint tokenizer backend checksum mismatch: {backend_sha}")
    if str(payload.get("tokenizer_id") or "") != _AGILLM43_REPAIR_TOKENIZER_ID:
        raise RuntimeError("checkpoint tokenizer_id mismatch")
    if not isinstance(special, dict):
        raise RuntimeError("checkpoint tokenizer special-token contract is missing")
    exact_special = {
        "vocab_size": _AGILLM43_REPAIR_VOCAB,
        "eos_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
        "pad_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
    }
    for name, expected in exact_special.items():
        if int(special.get(name, -1) or -1) != expected:
            raise RuntimeError(f"checkpoint tokenizer {name} mismatch")
    runtime = None
    if require_runtime:
        try:
            runtime_backend = tok.backend_tokenizer.to_str()
            runtime_backend_sha = hashlib.sha256(runtime_backend.encode("utf-8")).hexdigest()
            vocab = tok.get_vocab()
            runtime_vocab = max(vocab.values()) + 1
            runtime_pad = int(getattr(tok, "pad_token_id", -1))
            runtime_eos = int(getattr(tok, "eos_token_id", -1))
            runtime_mask = int(vocab.get(NAT_MASK_RECOVERY_TOKEN, -1))
        except Exception as exc:
            raise RuntimeError(f"cannot inspect restored tokenizer runtime: {exc}") from exc
        runtime = {
            "backend_sha256": runtime_backend_sha,
            "vocab_size": runtime_vocab,
            "pad_token_id": runtime_pad,
            "eos_token_id": runtime_eos,
            "nat_mask_token_id": runtime_mask,
            "active_nat_mask_token_id": int(NAT_MASK_ID),
        }
        expected_runtime = {
            "backend_sha256": _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256,
            "vocab_size": _AGILLM43_REPAIR_VOCAB,
            "pad_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
            "eos_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
            "nat_mask_token_id": _AGILLM43_REPAIR_NAT_MASK_ID,
            "active_nat_mask_token_id": _AGILLM43_REPAIR_NAT_MASK_ID,
        }
        if runtime != expected_runtime:
            raise RuntimeError(
                f"post-restore tokenizer runtime mismatch: {runtime!r} != {expected_runtime!r}")
        if int(VOCAB) != _AGILLM43_REPAIR_VOCAB or int(BLANK) != 1 or int(EOS) != 1:
            raise RuntimeError(
                f"import-time tokenizer globals drifted: VOCAB={VOCAB} BLANK={BLANK} EOS={EOS}")
    return {
        "schema": "agillm43.repair.tokenizer.v1",
        "tokenizer_id": _AGILLM43_REPAIR_TOKENIZER_ID,
        "seed_sidecar_sha256": _AGILLM43_REPAIR_TOKENIZER_SIDECAR_SHA256,
        "source_sidecar_path": str(sidecar_path.resolve()),
        "source_sidecar_sha256": sidecar_sha,
        "backend_sha256": backend_sha,
        "vocab_size": _AGILLM43_REPAIR_VOCAB,
        "eos_token_id": 1,
        "pad_token_id": 1,
        "nat_mask_token_id": 2,
        "import_runtime": import_runtime,
        "post_restore_runtime": runtime,
    }


