def _repair_nat_boundary_contract_errors(args):
    errors = []
    if getattr(args, "nat_document_boundary_aware", None) is not True:
        errors.append(
            "--nat_document_boundary_aware is required for packed-document NAT"
        )
    no_crop_limit_raw = getattr(
        args, "dblock_fullstack_nat_no_valid_crop_limit", None
    )
    if (
        isinstance(no_crop_limit_raw, bool)
        or not isinstance(no_crop_limit_raw, int)
        or no_crop_limit_raw != 8
    ):
        errors.append(
            "--dblock_fullstack_nat_no_valid_crop_limit must equal 8"
        )
    if getattr(
        args, "dblock_fullstack_anchor_deterministic_eval", None
    ) is not True:
        errors.append(
            "--dblock_fullstack_anchor_deterministic_eval is required"
        )
    for name in (
        "dblock_fullstack_anchor_spike_retry_limit",
        "dblock_local_spike_retry_limit",
    ):
        raw = getattr(args, name, None)
        if isinstance(raw, bool) or not isinstance(raw, int) or raw != 3:
            errors.append(f"--{name} must equal 3")
    for name, expected in (
        ("dblock_local_aux_warn_ce", 25.0),
        ("dblock_local_aux_max_ce", 50.0),
    ):
        raw = getattr(args, name, None)
        if (
            isinstance(raw, bool)
            or not isinstance(raw, (int, float))
            or not math.isfinite(float(raw))
            or float(raw) != expected
        ):
            errors.append(f"--{name} must equal {expected} as a finite number")
    return errors


_REPAIR_V14_ANCHOR_PROFILE = {
    "ar": {"every": 3, "offset": 0, "tokens": 128, "weight": 0.05},
    "sat": {"every": 3, "offset": 1, "tokens": 128, "weight": 0.10},
    "nat": {"every": 3, "offset": 2, "tokens": 128, "weight": 0.10},
}


def _repair_v14_anchor_contract_errors(args):
    """Validate the exact typed v14 AR/SAT/NAT composition profile."""
    errors = []
    for family, expected in _REPAIR_V14_ANCHOR_PROFILE.items():
        prefix = f"dblock_fullstack_{family}"
        actual = {}
        for suffix in ("every", "offset", "tokens"):
            name = f"{prefix}_{suffix}"
            raw = getattr(args, name, None)
            if type(raw) is not int:
                errors.append(f"--{name} must be an exact non-boolean integer")
                actual[suffix] = None
            else:
                actual[suffix] = raw
        weight_name = f"{prefix}_weight"
        weight_raw = getattr(args, weight_name, None)
        if (
            isinstance(weight_raw, bool)
            or not isinstance(weight_raw, (int, float))
            or not math.isfinite(float(weight_raw))
        ):
            errors.append(f"--{weight_name} must be a finite non-boolean number")
            actual["weight"] = None
        else:
            actual["weight"] = float(weight_raw)
        for suffix, expected_value in expected.items():
            if actual.get(suffix) != expected_value:
                errors.append(
                    f"--{prefix}_{suffix} must equal reviewed v14 value "
                    f"{expected_value}"
                )
    return errors


def _repair_contract_payload(args):
    fields = {name: getattr(args, name, None) for name in _REPAIR_CONTRACT_FIELDS}
    fields["repair_dataset_schema"] = _AGILLM43_REPAIR_DATASET_SCHEMA
    fields["repair_example_boundary_policy"] = (
        _AGILLM43_EXAMPLE_BOUNDARY_POLICY
    )
    fields["repair_target_commits"] = _AGILLM43_REPAIR_TARGET_COMMITS
    fields["repair_target_step"] = _AGILLM43_REPAIR_TARGET_STEP
    fields["repair_target_seen_tok"] = _AGILLM43_REPAIR_TARGET_SEEN_TOK
    return {
        "schema": _AGILLM_REPAIR_CONTRACT_SCHEMA,
        "fields": _dblock_json_copy(fields),
    }


def _repair_contract_sha256(payload):
    raw = json.dumps(
        payload, sort_keys=True, separators=(",", ":"), allow_nan=False
    ).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


